<script setup lang="ts">
import {computed,ref,onBeforeUnmount} from 'vue'
import LayoutPreview from './LayoutPreview.vue'
import {galleryLayouts as layoutLibrary,libraryGroups,type LayoutEntry} from './layout-library-model'
const query=ref(''),group=ref('전체'),selected=ref<LayoutEntry>(),dialog=ref<HTMLDialogElement>(),notice=ref('')
const results=computed(()=>layoutLibrary.filter(e=>(group.value==='전체'||e.group===group.value)&&`${e.name} ${e.id} ${e.relation} ${e.purpose} ${e.required.join(' ')}`.toLowerCase().includes(query.value.toLowerCase().trim())))
let opener:HTMLElement|null=null
function open(entry:LayoutEntry,event:Event){opener=event.currentTarget as HTMLElement;selected.value=entry;notice.value='';dialog.value?.showModal()}
function close(){dialog.value?.close();opener?.focus()}
function download(){if(!selected.value)return;const entry=selected.value;const blob=new Blob([JSON.stringify({schemaVersion:1,layoutId:entry.id,renderer:entry.renderer,canvas:{width:1040,height:entry.height},props:entry.props},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${entry.id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice.value='예시 JSON을 내려받았습니다. 실제 근거와 내용으로 교체해 사용하세요.'}
onBeforeUnmount(()=>dialog.value?.close())
</script>
<template>
 <main class="layout-library">
  <header class="library-header"><div><p class="library-eyebrow">ISPARK · PRESENTATION SYSTEM</p><h1>발표 레이아웃 라이브러리</h1><p>내용의 관계로 고르고, 같은 디자인으로 완성하세요.</p></div><a href="?path=/story/presentation-asset-library--gallery" target="_top">입체 아이콘 에셋 ↗</a></header>
  <div class="library-summary"><strong>{{layoutLibrary.length}}<span>재사용 레이아웃</span></strong><p>JDC 풍경 · 입체 그래픽 · 수정 가능한 텍스트<br><span>모든 예시는 디자인 검토용 가상 내용입니다.</span></p></div>
  <div class="library-toolbar"><nav aria-label="레이아웃 분류"><button v-for="category in ['전체',...libraryGroups]" :key="category" :class="{active:group===category}" :aria-pressed="group===category" @click="group=category">{{category}}</button></nav><label><span class="sr-only">레이아웃 검색</span><input v-model="query" type="search" placeholder="이름·용도·구조 검색"/></label></div>
  <p class="library-count" role="status">{{results.length}}개 레이아웃 · 미리보기에서 입력 항목과 사용 규칙을 확인하세요.</p>
  <div class="library-grid"><article v-for="entry in results" :key="entry.id" class="library-card"><div class="library-thumb"><LayoutPreview :entry="entry"/></div><div class="library-card-body"><div><span>{{entry.group}} · {{entry.relation}}</span><h2>{{entry.name}}</h2><p>{{entry.capacity}}</p></div><button :aria-label="`${entry.name} 미리보기`" @click="open(entry,$event)">미리보기 ↗</button></div></article></div>
  <div v-if="!results.length" class="library-empty"><h2>일치하는 레이아웃이 없습니다.</h2><p>검색어를 바꾸거나 다른 분류를 선택하세요.</p><button @click="query='';group='전체'">전체 보기</button></div>
  <footer class="library-footer">레이아웃 수는 이 프로젝트의 구성 기준입니다. 업계 공통 표준을 의미하지 않습니다. · 배경과 아이콘: AI 생성 자산</footer>
  <dialog ref="dialog" class="library-dialog" aria-labelledby="layout-dialog-title" @click="($event.target===dialog)&&close()" @close="opener?.focus()">
   <template v-if="selected"><header><div><span>{{selected.group}} / {{selected.relation}}</span><h2 id="layout-dialog-title">{{selected.name}}</h2></div><button autofocus aria-label="미리보기 닫기" @click="close">닫기 ×</button></header><div class="library-detail"><div class="library-large"><LayoutPreview :entry="selected"/><p>{{selected.purpose}}</p><span>텍스트·표·도식은 HTML 컴포넌트, 배경·입체 아이콘은 이미지 자산입니다.</span></div><aside><h3>사용 범위</h3><p>{{selected.capacity}}</p><h3>필수 입력</h3><ul><li v-for="field in selected.required" :key="field">{{field}}</li></ul><h3>선택 입력</h3><p>{{selected.optional.join(' · ')}}</p><h3>사용 규칙</h3><ul><li v-for="rule in selected.rules" :key="rule">{{rule}}</li></ul><p class="library-output">HTML·브라우저 PDF용<br>이 레이아웃의 PPTX 변환은 연결하지 않았습니다.</p><button class="library-download" @click="download">예시 JSON 내려받기</button><p role="status">{{notice}}</p><details><summary>입력 데이터 보기</summary><pre>{{JSON.stringify(selected.props,null,2)}}</pre></details></aside></div></template>
  </dialog>
 </main>
</template>
