olor:#526c7e}.library-detail aside{background:white;border:1px solid #d9e7f1;padding:20px;border-radius:12px;min-width:0;font-size:var(--type-source);line-height:1.65}.library-detail h3{font-size:var(--type-micro);margin:16px 0 6px}.library-detail h3:first-child{margin-top:0}.library-detail aside p{margin:0 0 10px}.library-detail ul{padding-left:18px;margin:0}.library-detail li{margin-bottom:6px}.library-output{margin-top:20px!important;font-size:var(--type-source);color:#526c7e;padding-top:15px;border-top:1px solid #d9e7f1}.library-download{background:#006fbd;border:0;color:white;border-radius:8px;width:100%;padding:12px;margin:8px 0}.library-detail pre{white-space:pre-wrap;word-break:break-all;font-size:var(--type-source);max-height:320px;overflow:auto;background:#f1f6fa;padding:10px}.library-detail summary{cursor:pointer;color:#006fbd}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}button:focus-visible,input:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid #f58220;outline-offset:3px}@media(max-width:1050px){.library-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.library-detail{grid-template-columns:minmax(0,1fr)}.library-detail aside{display:block}}@media(max-width:650px){.layout-library{padding:24px 14px}.library-grid{grid-template-columns:1fr}.library-header{display:block}.library-header a{display:inline-block;margin-top:18px}.library-header h1{font-size:var(--type-heading)}.library-summary{padding:16px;gap:16px}.library-summary p{padding-left:16px;font-size:var(--type-source)}.library-summary strong{font-size:var(--type-step)}.library-summary strong span{font-size:var(--type-micro)}.library-toolbar input{width:100%}.library-toolbar label{width:100%}}
